import{_ as p,r as n,o,c as l,e as s,a as r,s as c}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"Поле Number - October CMS - 3.x","titleTemplate":false,"description":"Поле формы","frontmatter":{"subtitle":"Поле формы","shortname":"Number"},"headers":[{"level":2,"title":"Серверная валидация","slug":"серверная-валидация","link":"#серверная-валидация","children":[]}],"relativePath":"3.x/ru/element/form/field-number.md","filePath":"3.x/ru/element/form/field-number.md"}'),u={name:"3.x/ru/element/form/field-number.md"};function d(i,a,k,m,g,y){const e=n("pre-heading"),t=n("post-heading");return o(),l("div",null,[s(e),a[0]||(a[0]=r("h1",null,"Поле Number",-1)),s(t),a[1]||(a[1]=c(`<p>Поле <code>number</code> рендерит однострочное текстовое поле, принимающее только числа.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">your_age</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Your Age
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
</code></pre></div><p>Поддерживаются и обычно используются следующие <a href="./../form-fields.html">свойства поля</a>.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя при отображении поля формы пользователю.</td></tr><tr><td><strong>default</strong></td><td>определяет значение строки по умолчанию, необязательно.</td></tr><tr><td><strong>comment</strong></td><td>размещает описательный комментарий под полем.</td></tr><tr><td><strong>min</strong></td><td>минимальное значение на стороне клиента, по умолчанию <code>null</code>.</td></tr><tr><td><strong>max</strong></td><td>максимальное значение на стороне клиента, по умолчанию <code>null</code>.</td></tr><tr><td><strong>step</strong></td><td>шаг инкремента на стороне клиента, по умолчанию <code>any</code>.</td></tr></tbody></table></div><p>Вы можете использовать свойства <code>min</code> и <code>max</code> для ограничения ввода минимальным и максимальным значениями. Следующее определение принимает только ввод от 1 до 100.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">your_age</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Your Age
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
    <span class="token key atrule">min</span><span class="token punctuation">:</span> <span class="token number">1</span>
    <span class="token key atrule">max</span><span class="token punctuation">:</span> <span class="token number">100</span>
</code></pre></div><p>Используйте свойство <code>step</code> для управления шагом увеличения или уменьшения числа, по умолчанию значение — <strong>any</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">your_age</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Your Age
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
    <span class="token key atrule">step</span><span class="token punctuation">:</span> <span class="token number">10</span>
</code></pre></div><h2 id="серверная-валидация"><a href="#серверная-валидация" class="header-anchor">#</a> Серверная валидация</h2><p>Если вы хотите валидировать это поле на стороне сервера при сохранении, чтобы убедиться, что оно числовое. При работе с полями Tailor используйте свойство <code>validation</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">your_age</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Your Age
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
    <span class="token key atrule">validation</span><span class="token punctuation">:</span> numeric
</code></pre></div><p>При работе с моделями используйте свойство <code>$rules</code> в вашей модели следующим образом.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;your_age&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;numeric&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Подробнее о валидации моделей см. в <a href="./../../extend/services/validation.html#rule-numeric">статье о сервисе валидации</a>.</p>`,14))])}const h=p(u,[["render",d]]);export{_ as __pageData,h as default};
